mapper.select:
SELECT , s.id as sys_id, s.system_code as sys_system_code, s.system_name as sys_system_name FROM openplat_app_auth a LEFT JOIN openplat_system s ON a.system_id = s.id
AND a.app_id LIKE CONCAT('%', #{appId}, '%')
AND a.system_id = #{systemId}
AND a.status = #{status}
ORDER BY a.create_time DESC

